"""Notices: generated by ticket events, filtered by audience in the query, read per user."""

from __future__ import annotations

import pytest

from tests.e2e.attachments_support import about, attach, child_of, notices, readable_png
from tests.e2e.closing_support import ready_operation, set_signature, sign
from tests.e2e.conftest import API
from tests.e2e.tickets_support import OPERATION, patch, ticket_url
from tests.e2e.tickets_support import make_operation as _plain_operation


async def make_operation(api, **extra):
    """An operation with top-level assignment fields (assigned_role_id, assigned_user_id)."""
    body = {"type_code": "operation", "title": "Vuelo de prueba", "payload": dict(OPERATION)}
    body.update(extra)
    if not extra:
        return await _plain_operation(api)
    r = await api.post(f"{API}/tickets/", json=body)
    assert r.status_code == 201, r.text
    return r.json()


NIL = "00000000-0000-0000-0000-000000000000"


@pytest.fixture
async def crew(logged):
    """One logged API per demo role, plus user ids."""
    emails = {
        "su": "super@transvalor.com",
        "ops": "operaciones@transvalor.com",
        "pilot": "piloto@transvalor.com",
        "maint": "mantenimiento@transvalor.com",
        "ground": "tierra@transvalor.com",
        "admin": "admin@transvalor.com",
    }
    apis, ids, roles = {}, {}, {}
    for key, email in emails.items():
        apis[key], body = await logged(email)
        ids[key] = body["user"]["id"]
        roles[key] = body["user"].get("role_id")
    apis["ids"], apis["roles"] = ids, roles
    return apis


async def receivers(crew, ticket, kind=None) -> list[str]:
    who = []
    for key in ("su", "ops", "pilot", "maint", "ground", "admin"):
        if await about(crew[key], ticket, kind):
            who.append(key)
    return sorted(who)


async def role_ids(admin) -> dict[str, str]:
    r = await admin.get(f"{API}/roles/?limit=100")
    return {x["code"]: x["id"] for x in r.json()["data"] if x.get("code")}


class TestCreationNotices:
    async def test_new_operation_notifies_only_operations(self, crew):
        op = await make_operation(crew["su"])
        assert await receivers(crew, op) == ["ops"]
        assert (await about(crew["ops"], op))[0]["kind"] == "operation_created"

    async def test_operation_for_another_role_notifies_that_role(self, crew):
        roles = await role_ids(crew["su"])
        op = await make_operation(crew["su"], assigned_role_id=roles["pilot"])
        assert await receivers(crew, op) == ["pilot"]

    async def test_a_named_responsible_gets_it_whatever_their_role(self, crew):
        roles = await role_ids(crew["su"])
        op = await make_operation(
            crew["su"], assigned_role_id=roles["pilot"], assigned_user_id=crew["ids"]["ground"]
        )
        assert await receivers(crew, op) == ["ground", "pilot"]

    async def test_superuser_does_not_get_foreign_audience_notices(self, crew):
        op = await make_operation(crew["su"])
        assert await about(crew["su"], op) == []

    async def test_child_with_a_role_notifies_only_that_role(self, crew):
        roles = await role_ids(crew["su"])
        op = await make_operation(crew["su"])
        ex = await child_of(crew["su"], op, "expense", assigned_role_id=roles["admin"])
        assert await receivers(crew, ex) == ["admin"]
        n = (await about(crew["admin"], ex))[0]
        assert n["kind"] == "ticket_assigned"
        assert n["ticket_id"] == ex["id"]
        assert n["operation_code"] == op["code"]

    async def test_child_never_leaks_to_unrelated_roles(self, crew):
        op = await make_operation(crew["su"])
        ex = await child_of(crew["su"], op, "expense")
        assert await about(crew["maint"], ex) == []
        assert await about(crew["ground"], ex) == []


class TestInacNotices:
    async def test_inac_notifies_operations_once(self, crew):
        op = await make_operation(crew["su"])
        inac = await child_of(crew["su"], op, "inac_permit")
        assert await receivers(crew, inac) == ["ops"]
        assert len(await about(crew["ops"], inac)) == 1
        assert (await about(crew["ops"], inac))[0]["kind"] == "navaid_pending"

    async def test_other_role_gets_assignment_and_operations_the_pending(self, crew):
        roles = await role_ids(crew["su"])
        op = await make_operation(crew["su"])
        inac = await child_of(crew["su"], op, "inac_permit", assigned_role_id=roles["admin"])
        assert [n["kind"] for n in await about(crew["admin"], inac)] == ["ticket_assigned"]
        assert [n["kind"] for n in await about(crew["ops"], inac)] == ["navaid_pending"]
        assert await about(crew["pilot"], inac) == []

    async def test_going_back_to_missing_navaid_raises_a_new_notice(self, crew):
        op = await make_operation(crew["su"])
        inac = await child_of(crew["su"], op, "inac_permit")
        assert (await patch(crew["su"], inac, status_code="pending_payment")).status_code == 200
        pending = await about(crew["ops"], inac, "navaid_pending")
        assert len(pending) == 2
        assert any("Falta radioayuda" in n["body"] for n in pending)

    async def test_final_approval_adds_no_pending_notice(self, crew):
        op = await make_operation(crew["su"])
        inac = await child_of(crew["su"], op, "inac_permit")
        await patch(crew["su"], inac, status_code="approved")
        assert len(await about(crew["ops"], inac, "navaid_pending")) == 1

    async def test_blocked_close_notifies_operations(self, crew):
        await set_signature(crew["su"])
        op = await ready_operation(crew["su"])
        inac = await child_of(crew["su"], op, "inac_permit")
        assert (await sign(crew["su"], op)).status_code == 201
        r = await patch(crew["su"], op, status_code="closed")
        assert r.status_code in (409, 422)
        blocked = await about(crew["ops"], op, "close_blocked")
        assert len(blocked) == 1
        assert inac["code"] in blocked[0]["body"]
        assert await receivers(crew, op, "close_blocked") == ["ops"]

    async def test_retrying_a_blocked_close_does_not_flood(self, crew):
        await set_signature(crew["su"])
        op = await ready_operation(crew["su"])
        await child_of(crew["su"], op, "inac_permit")
        await sign(crew["su"], op)
        for _ in range(3):
            await patch(crew["su"], op, status_code="closed")
        assert len(await about(crew["ops"], op, "close_blocked")) == 1

    async def test_a_close_blocked_for_other_reasons_has_no_inac_notice(self, crew):
        op = await make_operation(crew["su"])
        r = await patch(crew["su"], op, status_code="closed")
        assert r.status_code in (409, 422)
        assert await about(crew["ops"], op, "close_blocked") == []


class TestOtherEvents:
    async def test_technical_report_notifies_maintenance_only(self, crew):
        op = await make_operation(crew["su"])
        tr = await child_of(crew["su"], op, "technical_report")
        assert await receivers(crew, tr) == ["maint"]
        assert (await about(crew["maint"], tr))[0]["kind"] == "technical_report"

    async def test_technical_report_for_another_role_adds_that_role(self, crew):
        roles = await role_ids(crew["su"])
        op = await make_operation(crew["su"])
        tr = await child_of(crew["su"], op, "technical_report", assigned_role_id=roles["pilot"])
        assert await receivers(crew, tr) == ["maint", "pilot"]

    async def test_the_report_opened_by_the_system_is_silent(self, crew):
        op = await make_operation(crew["su"])
        r = await crew["su"].get(f"{API}/tickets/?parent_id={op['id']}&type_code=technical_report")
        for t in r.json()["data"]:
            assert await about(crew["maint"], t) == []

    async def test_a_read_receipt_notifies_admin_to_validate(self, crew):
        op = await make_operation(crew["su"])
        ex = await child_of(crew["su"], op, "expense")
        for _ in range(30):
            await attach(crew["su"], ex, "r.png", content=readable_png())
            if await about(crew["admin"], ex, "receipt_validation"):
                break
        assert await receivers(crew, ex, "receipt_validation") == ["admin"]

    async def test_a_pdf_receipt_raises_no_validation_notice(self, crew):
        op = await make_operation(crew["su"])
        ex = await child_of(crew["su"], op, "expense")
        await attach(crew["su"], ex, "r.pdf")
        assert await about(crew["admin"], ex, "receipt_validation") == []

    async def test_closing_notifies_operations_admin_and_crew(self, crew):
        await set_signature(crew["su"])
        op = await ready_operation(crew["su"])
        await sign(crew["su"], op)
        assert (await patch(crew["su"], op, status_code="closed")).status_code == 200
        assert await receivers(crew, op, "operation_closed") == ["admin", "ground", "ops", "pilot"]

    async def test_closing_reaches_the_named_responsible_too(self, crew):
        await set_signature(crew["su"])
        op = await ready_operation(
            crew["su"],
        )
        await crew["su"].patch(ticket_url(op), json={"assigned_user_id": crew["ids"]["maint"]})
        await sign(crew["su"], op)
        await patch(crew["su"], op, status_code="closed")
        assert len(await about(crew["maint"], op, "operation_closed")) == 1

    async def test_cancelling_is_not_announced_as_a_close(self, crew):
        op = await make_operation(crew["su"])
        assert (await patch(crew["su"], op, status_code="cancelled")).status_code == 200
        assert await receivers(crew, op, "operation_closed") == []


class TestAudienceFilter:
    async def test_each_user_sees_only_their_role_notices(self, crew):
        op = await make_operation(crew["su"])
        ex = await child_of(crew["su"], op, "technical_report")
        mine = {n["id"] for n in (await notices(crew["maint"]))["data"]}
        theirs = {n["id"] for n in (await notices(crew["pilot"]))["data"]}
        note = (await about(crew["maint"], ex))[0]["id"]
        assert note in mine and note not in theirs

    async def test_foreign_notice_is_404_not_403_and_stays_unread(self, crew):
        op = await make_operation(crew["su"])
        nid = (await about(crew["ops"], op))[0]["id"]
        before = (await notices(crew["ops"]))["unread"]
        r = await crew["pilot"].patch(f"{API}/notifications/{nid}/", json={})
        assert r.status_code == 404
        assert (await notices(crew["ops"]))["unread"] == before
        assert (await about(crew["ops"], op))[0]["read"] is False

    async def test_unknown_notice_is_404(self, crew):
        assert (
            await crew["pilot"].patch(f"{API}/notifications/{NIL}/", json={})
        ).status_code == 404

    async def test_malformed_id_is_422(self, crew):
        assert (await crew["pilot"].patch(f"{API}/notifications/nope/", json={})).status_code == 422

    async def test_no_session_is_401(self, anon):
        assert (await anon.get(f"{API}/notifications/")).status_code == 401
        assert (await anon.patch(f"{API}/notifications/{NIL}/", json={})).status_code == 401
        assert (await anon.post(f"{API}/notifications/read-all/")).status_code == 401

    async def test_newest_first(self, crew):
        await make_operation(crew["su"])
        await make_operation(crew["su"])
        dates = [n["created_at"] for n in (await notices(crew["ops"]))["data"]]
        assert dates == sorted(dates, reverse=True)

    async def test_a_user_without_the_permission_gets_403(self, new_account):
        api, _, _ = await new_account(["tickets.view"])
        assert (await api.get(f"{API}/notifications/")).status_code == 403

    async def test_filters_are_whitelisted_and_typed(self, crew):
        assert (await crew["ops"].get(f"{API}/notifications/?ticket_id=nope")).status_code == 422
        assert (await crew["ops"].get(f"{API}/notifications/?limit=0")).status_code == 422
        assert (await crew["ops"].get(f"{API}/notifications/?limit=9999")).status_code == 422

    async def test_unknown_filter_does_not_widen_the_audience(self, crew):
        op = await make_operation(crew["su"])
        r = await crew["pilot"].get(f"{API}/notifications/?audience=operations&role_id=x&limit=100")
        assert r.status_code == 200
        assert all(n["ticket_id"] != op["id"] for n in r.json()["data"])

    async def test_filter_by_ticket_and_kind(self, crew):
        op = await make_operation(crew["su"])
        await make_operation(crew["su"])
        r = await notices(crew["ops"], ticket_id=op["id"], kind="operation_created")
        assert [n["ticket_id"] for n in r["data"]] == [op["id"]]

    async def test_audience_is_shown_as_role_names(self, crew):
        op = await make_operation(crew["su"])
        n = (await about(crew["ops"], op))[0]
        assert n["audience"] and all(isinstance(a, str) for a in n["audience"])
        assert "user_id" not in n and "users" not in n


class TestReadState:
    async def test_marking_read_is_personal(self, crew):
        roles = await role_ids(crew["su"])
        op = await make_operation(
            crew["su"], assigned_role_id=roles["pilot"], assigned_user_id=crew["ids"]["ground"]
        )
        nid = (await about(crew["pilot"], op))[0]["id"]
        assert (await about(crew["ground"], op))[0]["id"] == nid
        assert (
            await crew["pilot"].patch(f"{API}/notifications/{nid}/", json={})
        ).status_code == 200
        assert (await about(crew["pilot"], op))[0]["read"] is True
        assert (await about(crew["ground"], op))[0]["read"] is False

    async def test_unread_drops_only_for_the_reader(self, crew):
        roles = await role_ids(crew["su"])
        op = await make_operation(
            crew["su"], assigned_role_id=roles["pilot"], assigned_user_id=crew["ids"]["ground"]
        )
        nid = (await about(crew["pilot"], op))[0]["id"]
        pilot, ground = (await notices(crew["pilot"]))["unread"], (await notices(crew["ground"]))[
            "unread"
        ]
        await crew["pilot"].patch(f"{API}/notifications/{nid}/", json={})
        assert (await notices(crew["pilot"]))["unread"] == pilot - 1
        assert (await notices(crew["ground"]))["unread"] == ground

    async def test_marking_twice_counts_once(self, crew):
        op = await make_operation(crew["su"])
        nid = (await about(crew["ops"], op))[0]["id"]
        before = (await notices(crew["ops"]))["unread"]
        for _ in range(2):
            assert (
                await crew["ops"].patch(f"{API}/notifications/{nid}/", json={})
            ).status_code == 200
        assert (await notices(crew["ops"]))["unread"] == before - 1

    async def test_marking_unread_again(self, crew):
        op = await make_operation(crew["su"])
        nid = (await about(crew["ops"], op))[0]["id"]
        await crew["ops"].patch(f"{API}/notifications/{nid}/", json={})
        r = await crew["ops"].patch(f"{API}/notifications/{nid}/", json={"read": False})
        assert r.status_code == 200 and r.json()["read"] is False

    async def test_a_new_notice_raises_only_its_audience_count(self, crew):
        ops, maint = (await notices(crew["ops"]))["unread"], (await notices(crew["maint"]))[
            "unread"
        ]
        await make_operation(crew["su"])
        assert (await notices(crew["ops"]))["unread"] == ops + 1
        assert (await notices(crew["maint"]))["unread"] == maint

    async def test_unread_is_the_total_not_the_page(self, crew):
        await make_operation(crew["su"])
        await make_operation(crew["su"])
        full = await notices(crew["ops"])
        paged = await notices(crew["ops"], limit=1)
        assert len(paged["data"]) == 1
        assert paged["unread"] == (await notices(crew["ops"], unread="true", limit=1))["total"]
        assert paged["total"] == full["total"]

    async def test_unread_filter(self, crew):
        op = await make_operation(crew["su"])
        nid = (await about(crew["ops"], op))[0]["id"]
        await crew["ops"].patch(f"{API}/notifications/{nid}/", json={})
        r = await notices(crew["ops"], unread="true")
        assert all(n["read"] is False for n in r["data"])
        assert nid not in {n["id"] for n in r["data"]}

    async def test_read_all_marks_only_mine(self, crew):
        await make_operation(crew["su"])
        await make_operation(crew["su"])
        roles = await role_ids(crew["su"])
        await make_operation(crew["su"], assigned_role_id=roles["pilot"])
        pilot = (await notices(crew["pilot"]))["unread"]
        r = await crew["ops"].post(f"{API}/notifications/read-all/")
        assert r.status_code == 200
        assert r.json()["unread"] == 0 and r.json()["marked"] >= 2
        assert (await notices(crew["ops"]))["unread"] == 0
        assert (await notices(crew["pilot"]))["unread"] == pilot

    async def test_read_all_twice_marks_nothing_new(self, crew):
        await make_operation(crew["su"])
        await crew["ops"].post(f"{API}/notifications/read-all/")
        r = await crew["ops"].post(f"{API}/notifications/read-all/")
        assert r.json() == {"marked": 0, "unread": 0}

    async def test_read_state_survives_new_notices(self, crew):
        op = await make_operation(crew["su"])
        nid = (await about(crew["ops"], op))[0]["id"]
        await crew["ops"].patch(f"{API}/notifications/{nid}/", json={})
        await make_operation(crew["su"])
        assert (await about(crew["ops"], op))[0]["read"] is True

    async def test_cannot_set_other_fields_through_patch(self, crew):
        op = await make_operation(crew["su"])
        nid = (await about(crew["ops"], op))[0]["id"]
        r = await crew["ops"].patch(
            f"{API}/notifications/{nid}/", json={"read": True, "title": "x", "audience": ["a"]}
        )
        assert r.status_code in (200, 422)
        n = (await about(crew["ops"], op))[0]
        assert n["title"] != "x"
